import{_ as a,o,c as r,a3 as t}from"./chunks/framework.zpJ7aH3B.js";const m=JSON.parse('{"title":"Roles","description":"","frontmatter":{},"headers":[],"relativePath":"roles/index.md","filePath":"roles/index.md"}'),n={name:"roles/index.md"};function i(s,e,l,d,c,p){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="roles" tabindex="-1">Roles <a class="header-anchor" href="#roles" aria-label="Permalink to &quot;Roles&quot;">​</a></h1><p>ShipperDog&#39;s role catalog maps to nine documentation personas. Each persona gets a dedicated quickstart ending in a hand-off task list; the quickstarts land in the WP4 rollout (see <a href="https://github.com/ShristiLabs/shipperdog/blob/main/docs-site/PLAN.md" target="_blank" rel="noreferrer">the plan</a>).</p><h2 id="platform-operator" tabindex="-1">Platform Operator <a class="header-anchor" href="#platform-operator" aria-label="Permalink to &quot;Platform Operator&quot;">​</a></h2><p><code>platform_admin</code> — Console and Terraform. Org onboarding, instance health, cross-tenant operations, break-glass.</p><h2 id="organization-admin" tabindex="-1">Organization Admin <a class="header-anchor" href="#organization-admin" aria-label="Permalink to &quot;Organization Admin&quot;">​</a></h2><p><code>ORG_ADMIN</code> — Console. Members and roles, tenants, IdP/SCIM/SSO configuration, channel credentials, ABAC and SIEM policies.</p><h2 id="release-manager" tabindex="-1">Release Manager <a class="header-anchor" href="#release-manager" aria-label="Permalink to &quot;Release Manager&quot;">​</a></h2><p><code>RELEASE_MANAGER</code> — Console and CLI. Release creation through approvals, gates, ring promotion, staged rollout, and rollback.</p><h2 id="app-owner-product" tabindex="-1">App Owner / Product <a class="header-anchor" href="#app-owner-product" aria-label="Permalink to &quot;App Owner / Product&quot;">​</a></h2><p><code>APP_OWNER</code> — Console. App registry, ownership scope, product approvals, release manifests, dashboards.</p><h2 id="developer" tabindex="-1">Developer <a class="header-anchor" href="#developer" aria-label="Permalink to &quot;Developer&quot;">​</a></h2><p><code>DEVELOPER</code> — CLI, CI, and Console. Artifact upload with provenance, versions and tags, CI actions (GitHub Actions, Jenkins, GitLab), gate feedback.</p><h2 id="qa-engineer" tabindex="-1">QA Engineer <a class="header-anchor" href="#qa-engineer" aria-label="Permalink to &quot;QA Engineer&quot;">​</a></h2><p><code>QA_ENGINEER</code> — Console and Portal admin views. Tester groups, feedback triage, crash-free gates, device fleet.</p><h2 id="security-compliance-reviewer" tabindex="-1">Security / Compliance Reviewer <a class="header-anchor" href="#security-compliance-reviewer" aria-label="Permalink to &quot;Security / Compliance Reviewer&quot;">​</a></h2><p><code>SECURITY_REVIEWER</code>, <code>COMPLIANCE_REVIEWER</code> — Console. Security feedback, approval signatures, audit trail, SIEM streams.</p><h2 id="tenant-admin" tabindex="-1">Tenant Admin <a class="header-anchor" href="#tenant-admin" aria-label="Permalink to &quot;Tenant Admin&quot;">​</a></h2><p><code>TENANT_ADMIN</code> — Console, tenant-scoped. Tenant members, devices, tenant dashboard, app visibility.</p><h2 id="tester" tabindex="-1">Tester <a class="header-anchor" href="#tester" aria-label="Permalink to &quot;Tester&quot;">​</a></h2><p><code>TENANT_TESTER</code> — Tester Portal and the companion app. Accept an invite, browse apps, install builds, submit feedback. The one persona with zero Console access — the Portal track is fully standalone: invite email to first install in under five minutes.</p>',20)])])}const u=a(n,[["render",i]]);export{m as __pageData,u as default};
